/// Gets the canonical decomposition of a code point
/// Returns null if no decomposition exists
/// Uses block index for O(1) narrowing, then short binary search within block
pub fn getDecomposition(cp: Codepoint) ?[]const Codepoint {
    // Check each length table with block-indexed binary search
    if (blockSearchDecomp1(cp)) |result| {
        return &result.decomp;
    }
    if (blockSearchDecomp2(cp)) |result| {
        return &result.decomp;
    }
    return null;
}

fn blockSearchDecomp1(cp: Codepoint) ?*const DecompEntry1 {
    const block = @as(usize, cp >> 8);
    if (block >= decomp1_block_index.len) return null;
    const range = decomp1_block_index[block];
    var left: usize = range[0];
    var right: usize = range[1];
    while (left < right) {
        const mid = left + (right - left) / 2;
        if (decomp_len1[mid].cp == cp) {
            return &decomp_len1[mid];
        } else if (decomp_len1[mid].cp < cp) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return null;
}

fn blockSearchDecomp2(cp: Codepoint) ?*const DecompEntry2 {
    const block = @as(usize, cp >> 8);
    if (block >= decomp2_block_index.len) return null;
    const range = decomp2_block_index[block];
    var left: usize = range[0];
    var right: usize = range[1];
    while (left < right) {
        const mid = left + (right - left) / 2;
        if (decomp_len2[mid].cp == cp) {
            return &decomp_len2[mid];
        } else if (decomp_len2[mid].cp < cp) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return null;
}
